// SPDX-License-Identifier: MIT
// Shardfall Gamble (Prismheart campaign), plain C++17 for the Unreal binding. A port of
// tools/minigames/shardfall.py (prism-shard-dev), which stays the rules authority. Seeding is CPython-compatible
// (DaedalusPyRandomCore.h, "shardfall:<seed>:<difficulty>"); each round's seam bag is shuffled like Python's shuffle.
// Byte parity goes through engines/unreal/core-test/shardfall_parity.txt (shardfall_core_test.cpp), generated by
// tools/minigames/shardfall_parity.py.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <cstdint>
#include <string>
#include <vector>

namespace daedalus { namespace shardfall {

inline const char* GameId() { return "shardfall"; }
inline const char* Title() { return "Shardfall Gamble"; }
constexpr int BustAt = 2;
constexpr int ValueCount = 12;
inline const int* Values() { static const int V[ValueCount] = { 1, 1, 2, 2, 2, 3, 3, 3, 4, 4, 5, 5 }; return V; }

struct Difficulty { const char* Name; int Rounds; int Target; int Cracked; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 6, 40, 2 }, { "normal", 5, 40, 3 }, { "hard", 4, 32, 4 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

constexpr int BoonDelta = -1;  // Spirit Boon (Hollow Moth): cracked -1 per level (hephaestus R2-9; level 2 = 5+ summons)
/** FindDifficulty with a Spirit Boon level 0..2 applied to Cracked (PrismGame boon, floor 0). Nullptr on a bad level. */
inline const Difficulty* FindDifficulty(const std::string& Name, int Boon)
{
	if (Boon == 0) return FindDifficulty(Name);
	if (Boon < 0 || Boon > 2) return nullptr;
	struct Boosted { Difficulty Table[2][DifficultyCount]; };
	static const Boosted B = [] {
		Boosted Out{};
		for (int L = 0; L < 2; ++L)
			for (int I = 0; I < DifficultyCount; ++I)
			{
				Out.Table[L][I] = Difficulties()[I];
				Out.Table[L][I].Cracked = std::max(0, Out.Table[L][I].Cracked + BoonDelta * (L + 1));
			}
		return Out;
	}();
	for (int I = 0; I < DifficultyCount; ++I)
	{
		if (Name == B.Table[Boon - 1][I].Name) return &B.Table[Boon - 1][I];
	}
	return nullptr;
}

struct Game
{
	const Difficulty* Diff = nullptr;
	int Round = 0, Pot = 0, Cracks = 0;
	std::vector<int> Bag;          // 0 = cracked; drawn from the back like list.pop()
	std::vector<int> History;      // banked per round
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	int CrackedLeft() const { int N = 0; for (int V : Bag) if (V == 0) ++N; return N; }

	void Open()
	{
		++Round; Pot = Cracks = 0;
		Bag.assign(Values(), Values() + ValueCount);
		for (int I = 0; I < Diff->Cracked; ++I) Bag.push_back(0);
		Rng.Shuffle(Bag);
	}

	bool Start(std::uint32_t Seed, const std::string& DifficultyName, int Boon = 0)
	{
		Diff = FindDifficulty(DifficultyName, Boon);
		if (!Diff) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false; Round = 0; History.clear();
		Open();
		return true;
	}

	void EndRound(int Banked)
	{
		History.push_back(Banked); Score += Banked;
		if (Score >= Diff->Target) { Over = true; Won = true; }
		else if (Round >= Diff->Rounds) { Over = true; Won = false; }
		else Open();
	}

	enum class Act : int { Ok = 0, GameOver, EmptySeam };
	enum class Draw : int { Value = 0, Cracked, Collapse };

	/** Draw the top shard. `Value` receives the shard's worth (0 for cracked). */
	Act DrawShard(Draw& Out, int& Value)
	{
		Out = Draw::Value; Value = 0;
		if (Over) return Act::GameOver;
		if (Bag.empty()) return Act::EmptySeam;
		const int V = Bag.back(); Bag.pop_back();
		if (V == 0)
		{
			++Cracks;
			if (Cracks >= BustAt) { EndRound(0); Out = Draw::Collapse; return Act::Ok; }
			Out = Draw::Cracked; return Act::Ok;
		}
		Pot += V; Value = V; return Act::Ok;
	}

	Act Bank(int& Banked)
	{
		Banked = 0;
		if (Over) return Act::GameOver;
		Banked = Pot; EndRound(Pot); return Act::Ok;
	}

	double Risk() const { return (!Bag.empty() && Cracks >= BustAt - 1) ? static_cast<double>(CrackedLeft()) / static_cast<double>(Bag.size()) : 0.0; }
	/** shardfall.Game.demo_action: true = bank. */
	bool DemoBank() const { return Bag.empty() || Pot >= 12 || (Pot >= 5 && Risk() > 0.15); }

	std::string BagString() const { std::string S; for (size_t I = 0; I < Bag.size(); ++I) { if (I) S.push_back(','); S += std::to_string(Bag[I]); } return S.empty() ? "-" : S; }
	std::string HistoryString() const { std::string S; for (size_t I = 0; I < History.size(); ++I) { if (I) S.push_back(','); S += std::to_string(History[I]); } return S.empty() ? "-" : S; }
};

} } // namespace daedalus::shardfall
